-- Libera collab server: initial schema (Phases 1–4).
-- Tables follow the source plan §5.2 and collaboration map §8.
-- Ids are text (prefixed random ids generated by the server or the client).

create table accounts (
  id text primary key,
  email text not null,
  display_name text not null,
  color text not null,
  password_hash text not null,
  created_at timestamptz not null default now(),
  disabled_at timestamptz
);
create unique index accounts_email_key on accounts (lower(email));

create table refresh_tokens (
  id text primary key,
  account_id text not null references accounts (id) on delete cascade,
  token_hash text not null unique,
  -- All tokens produced by rotating one login share a family. Reusing a
  -- rotated token revokes the whole family.
  family_id text not null,
  device_name text,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  replaced_by text
);
create index refresh_tokens_account_idx on refresh_tokens (account_id);
create index refresh_tokens_family_idx on refresh_tokens (family_id);

create table projects (
  id text primary key,
  name text not null,
  owner_id text not null references accounts (id),
  manifest_doc_id text not null,
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table memberships (
  project_id text not null references projects (id) on delete cascade,
  account_id text not null references accounts (id) on delete cascade,
  role text not null check (role in ('owner', 'editor', 'commenter', 'viewer')),
  created_at timestamptz not null default now(),
  primary key (project_id, account_id)
);
create index memberships_account_idx on memberships (account_id);

create table invitations (
  id text primary key,
  project_id text not null references projects (id) on delete cascade,
  email text not null,
  role text not null check (role in ('editor', 'commenter', 'viewer')),
  token_hash text not null unique,
  invited_by text not null references accounts (id),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  accepted_at timestamptz,
  accepted_by text references accounts (id),
  revoked_at timestamptz
);
create index invitations_project_idx on invitations (project_id);

create table documents (
  id text primary key,
  project_id text not null references projects (id) on delete cascade,
  kind text not null check (kind in ('markdown', 'latex', 'text', 'manifest')),
  file_id text,
  schema_version integer not null default 1,
  -- Highest server_seq persisted. Updated in the same transaction as each
  -- doc_updates insert; the sync room serializes writes per document.
  last_server_seq bigint not null default 0,
  created_by text references accounts (id),
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index documents_project_idx on documents (project_id);

create table doc_updates (
  doc_id text not null references documents (id) on delete cascade,
  subdoc text not null check (subdoc in ('content', 'annotations', 'meta', 'manifest')),
  server_seq bigint not null,
  account_id text references accounts (id),
  client_id text not null,
  client_seq bigint not null,
  actor jsonb,
  provenance jsonb,
  update bytea not null,
  size integer not null,
  received_at timestamptz not null default now(),
  primary key (doc_id, server_seq),
  -- Makes resends idempotent (§5.2).
  unique (doc_id, client_id, client_seq)
);
create index doc_updates_subdoc_idx on doc_updates (doc_id, subdoc, server_seq);

create table doc_snapshots (
  doc_id text not null references documents (id) on delete cascade,
  subdoc text not null check (subdoc in ('content', 'annotations', 'meta', 'manifest')),
  upto_server_seq bigint not null,
  state bytea not null,
  state_vector bytea not null,
  created_at timestamptz not null default now(),
  primary key (doc_id, subdoc, upto_server_seq)
);

create table revisions (
  id text primary key,
  doc_id text not null references documents (id) on delete cascade,
  server_seq bigint not null,
  label text,
  kind text not null check (kind in ('auto', 'named', 'session-end', 'pre-accept-all', 'pre-restore', 'review-base')),
  created_by text references accounts (id),
  created_at timestamptz not null default now()
);
create index revisions_doc_idx on revisions (doc_id, server_seq);

create table blobs (
  project_id text not null references projects (id) on delete cascade,
  hash text not null,
  size bigint not null,
  mime text not null,
  created_by text references accounts (id),
  created_at timestamptz not null default now(),
  primary key (project_id, hash)
);

create table threads (
  id text primary key,
  doc_id text not null references documents (id) on delete cascade,
  project_id text not null references projects (id) on delete cascade,
  anchor_id text not null,
  quote_text text not null,
  status text not null check (status in ('open', 'resolved', 'detached')),
  actor jsonb not null,
  account_id text not null references accounts (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  resolved_by text references accounts (id),
  resolved_at timestamptz,
  deleted_at timestamptz
);
create index threads_doc_idx on threads (doc_id);

create table messages (
  id text primary key,
  thread_id text not null references threads (id) on delete cascade,
  actor jsonb not null,
  account_id text not null references accounts (id),
  body text not null,
  mentions jsonb not null default '[]',
  created_at timestamptz not null default now(),
  edited_at timestamptz,
  deleted_at timestamptz
);
create index messages_thread_idx on messages (thread_id, created_at);

create table suggestions (
  id text primary key,
  doc_id text not null references documents (id) on delete cascade,
  project_id text not null references projects (id) on delete cascade,
  group_id text,
  actor jsonb not null,
  account_id text not null references accounts (id),
  base_quote text not null,
  replacement text not null,
  status text not null check (status in ('pending', 'accepted', 'rejected', 'stale', 'withdrawn')),
  thread_ids jsonb not null default '[]',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  decided_by text references accounts (id),
  decided_at timestamptz,
  decision_server_seq bigint,
  stale_reason text
);
create index suggestions_doc_idx on suggestions (doc_id, status);

create table reviews (
  id text primary key,
  doc_id text not null references documents (id) on delete cascade,
  project_id text not null references projects (id) on delete cascade,
  requested_by text not null references accounts (id),
  base_revision_id text not null references revisions (id),
  scope jsonb not null,
  note text not null default '',
  status text not null check (status in ('open', 'approved', 'changes-requested', 'closed')),
  created_at timestamptz not null default now(),
  closed_at timestamptz
);
create index reviews_doc_idx on reviews (doc_id);

create table review_assignments (
  review_id text not null references reviews (id) on delete cascade,
  account_id text not null references accounts (id),
  decision text not null default 'pending' check (decision in ('pending', 'approved', 'changes-requested')),
  decided_revision_id text references revisions (id),
  decided_server_seq bigint,
  decided_at timestamptz,
  outdated boolean not null default false,
  primary key (review_id, account_id)
);

create table notifications (
  id text primary key,
  account_id text not null references accounts (id) on delete cascade,
  project_id text references projects (id) on delete cascade,
  doc_id text references documents (id) on delete cascade,
  kind text not null,
  payload jsonb not null default '{}',
  created_at timestamptz not null default now(),
  read_at timestamptz,
  emailed_at timestamptz
);
create index notifications_account_idx on notifications (account_id, created_at desc);

create table commands (
  account_id text not null references accounts (id) on delete cascade,
  id text not null,
  kind text not null,
  status integer not null,
  result jsonb,
  created_at timestamptz not null default now(),
  primary key (account_id, id)
);

create table audit_log (
  id bigserial primary key,
  project_id text references projects (id) on delete cascade,
  actor jsonb,
  account_id text references accounts (id),
  action text not null,
  target text not null,
  details jsonb not null default '{}',
  at timestamptz not null default now()
);
create index audit_log_project_idx on audit_log (project_id, at desc);
